 async function select(id){id=configId(id);if(ready&&visible(id)&&!free.has(id)&&!signed){if(typeof openLogin==='function')openLogin('登录后才能切换会员主题。');else if(typeof show==='function')show('#login');return}const ticket=++selection;if(ready&&visible(id)&&entitled.has(id)){lockedVisual=false;lockedTheme='';originalChangeTheme(id);await updatePresence(true);prune();return}try{const data=await fetchAccess(id);if(ticket!==selection)return;if(!allowed(id)){const error=Error(visible(id)?'今天的体验先到这里，开通会员后可以继续使用。':'主题暂不可用');error.memberRequired=visible(id)&&!entitled.has(id);throw error}lockedVisual=false;lockedTheme='';originalChangeTheme(id);await updatePresence(true);prune()}catch(error){if(ticket!==selection||error.staleAccount)return;if(sanitize())render();if(error.memberRequired&&typeof memberGate==='function')memberGate('themes',{themeId:id});else toast(error.message)}}
